-- The models of Udozo's brands (2 November 2026): sellers pick one for the `model` feature once they have chosen a brand,
-- and buyers filter by it. A model is a brand's in one category, so Samsung's phones and its TVs are different lists.

CREATE TABLE "classified_brand_models" (
    "id" UUID NOT NULL,
    "brand_id" UUID NOT NULL,
    "category_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "name_key" TEXT NOT NULL,
    "aliases" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "match_keys" TEXT[] DEFAULT ARRAY[]::TEXT[],
    "position" INTEGER NOT NULL DEFAULT 0,
    "source" TEXT NOT NULL DEFAULT 'registry',
    "enabled" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "classified_brand_models_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "classified_brand_models_brand_id_category_id_name_key_key" ON "classified_brand_models"("brand_id", "category_id", "name_key");
CREATE INDEX "classified_brand_models_category_id_brand_id_position_idx" ON "classified_brand_models"("category_id", "brand_id", "position");
ALTER TABLE "classified_brand_models" ADD CONSTRAINT "classified_brand_models_brand_id_fkey" FOREIGN KEY ("brand_id") REFERENCES "classified_brands"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "classified_brand_models" ADD CONSTRAINT "classified_brand_models_category_id_fkey" FOREIGN KEY ("category_id") REFERENCES "classified_categories"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "classified_brand_models" ADD CONSTRAINT "classified_brand_models_name_check" CHECK (char_length("name") BETWEEN 1 AND 60 AND char_length("name_key") >= 1);
ALTER TABLE "classified_brand_models" ADD CONSTRAINT "classified_brand_models_source_check" CHECK ("source" IN ('registry', 'admin', 'sellers'));

CREATE TABLE "classified_model_suggestions" (
    "id" UUID NOT NULL,
    "customer_id" UUID NOT NULL,
    "brand_id" UUID NOT NULL,
    "category_id" UUID NOT NULL,
    "name" TEXT NOT NULL,
    "name_key" TEXT NOT NULL,
    "status" TEXT NOT NULL DEFAULT 'open',
    "model_id" UUID,
    "decided_by_id" UUID,
    "decided_at" TIMESTAMP(3),
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT "classified_model_suggestions_pkey" PRIMARY KEY ("id")
);

CREATE INDEX "classified_model_suggestions_status_brand_id_category_id_name_key_idx" ON "classified_model_suggestions"("status", "brand_id", "category_id", "name_key");
CREATE INDEX "classified_model_suggestions_customer_id_created_at_idx" ON "classified_model_suggestions"("customer_id", "created_at");
-- One open suggestion per seller, brand, category and model.
CREATE UNIQUE INDEX "classified_model_suggestions_open_key" ON "classified_model_suggestions"("customer_id", "brand_id", "category_id", "name_key") WHERE "status" = 'open';
ALTER TABLE "classified_model_suggestions" ADD CONSTRAINT "classified_model_suggestions_customer_id_fkey" FOREIGN KEY ("customer_id") REFERENCES "customers"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "classified_model_suggestions" ADD CONSTRAINT "classified_model_suggestions_brand_id_fkey" FOREIGN KEY ("brand_id") REFERENCES "classified_brands"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "classified_model_suggestions" ADD CONSTRAINT "classified_model_suggestions_category_id_fkey" FOREIGN KEY ("category_id") REFERENCES "classified_categories"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "classified_model_suggestions" ADD CONSTRAINT "classified_model_suggestions_model_id_fkey" FOREIGN KEY ("model_id") REFERENCES "classified_brand_models"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "classified_model_suggestions" ADD CONSTRAINT "classified_model_suggestions_status_check" CHECK ("status" IN ('open', 'added', 'dismissed'));
ALTER TABLE "classified_model_suggestions" ADD CONSTRAINT "classified_model_suggestions_decided_check" CHECK (("status" = 'open') = ("decided_at" IS NULL));

-- Buyers filter by model once they have chosen a brand.
UPDATE "classified_features" SET "filterable" = true, "updated_at" = CURRENT_TIMESTAMP WHERE "key" = 'model';

-- Generators and inverters are bought by model too.
INSERT INTO "classified_category_features" ("category_id", "feature_id", "position", "filter")
SELECT c."id", f."id", 1, false
FROM "classified_categories" c, "classified_features" f
WHERE c."slug" = 'generators-solar' AND f."key" = 'model'
ON CONFLICT DO NOTHING;

