INSERT INTO "classified_brand_categories" ("brand_id", "category_id", "position")
SELECT b."id", c."id", 1000 + row_number() OVER ()
FROM (VALUES
  ('toyota', 'heavy-equipment'),
  ('doosan', 'heavy-equipment'),
  ('perkins', 'industrial-machinery'),
  ('cummins', 'industrial-machinery'),
  ('honda', 'industrial-machinery'),
  ('instantpot', 'kitchen-appliances'),
  ('nespresso', 'kitchen-appliances'),
  ('nutribullet', 'kitchen-appliances'),
  ('hmd', 'mobile-phones'),
  ('iqoo', 'mobile-phones'),
  ('mobvoi', 'smart-watches'),
  ('casio', 'smart-watches'),
  ('withings', 'smart-watches'),
  ('zeblaze', 'smart-watches')
) AS v("brand", "category")
JOIN "classified_brands" b ON b."name_key" = v."brand"
JOIN "classified_categories" c ON c."slug" = v."category"
ON CONFLICT DO NOTHING;

