JOIN "classified_brands" b ON b."name_key" = v."brand"
JOIN "classified_categories" c ON c."slug" = v."category";

-- Models already on listings read as the list writes them ("s23 ultra" becomes Galaxy S23 Ultra).
UPDATE "classified_listing_features" lf SET "value_text" = m."name"
FROM "classified_listings" l, "classified_brand_models" m, "classified_listing_features" lb, "classified_features" fb, "classified_brands" b
WHERE l."id" = lf."listing_id"
  AND lf."feature_id" = (SELECT "id" FROM "classified_features" WHERE "key" = 'model')
  AND lb."listing_id" = l."id" AND lb."feature_id" = fb."id" AND fb."key" = 'brand'
  AND b."name" = lb."value_text"
  AND m."brand_id" = b."id" AND m."category_id" = l."category_id"
  AND regexp_replace(translate(lower(lf."value_text"), 'àáâäãåçèéêëìíîïñòóôöõùúûüýÿšžčćœ', 'aaaaaaceeeeiiiinooooouuuuyyszcco'), '[^a-z0-9]', '', 'g') = ANY(m."match_keys")
  AND lf."value_text" <> m."name";
